Python (<code>main.py</code>) <pre><code>from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import OAuth2PasswordRequestForm
from auth import verify_password, get_password_hash, create_access_token
from dependencies import get_current_user

app = FastAPI(title="FastAPI JWT Authentication")

users_db = {
    "bob": {
        "username": "bob",
        "hashed_password": get_password_hash("secret123"),
        "email": "bob@example.com"
    }
}

# ── LOGIN / TOKEN GENERATION ─────────────────────────────────
@app.post("/token")
def login_for_access_token(form_data: OAuth2PasswordRequestForm = Depends()):
    user = users_db.get(form_data.username)
    if not user or not verify_password(form_data.password, user["hashed_password"]):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
            headers={"WWW-Authenticate": "Bearer"},
        )
    access_token = create_access_token(data={"sub": user["username"]})
    return {"access_token": access_token, "token_type": "bearer"}

# ── PROTECTED ENDPOINTS ──────────────────────────────────────
@app.get("/users/me")
def read_users_me(current_user: dict = Depends(get_current_user)):
    return current_user

@app.get("/admin/stats")
def read_admin_stats(current_user: dict = Depends(get_current_user)):
    if current_user.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Admin privilege required")
    return {"active_users": 1500, "server_load": "12%"}
