PythonOutput <pre><code>import time

def resolve(code: str) -&gt; dict:
    """Look up a short code and track the click."""
    entry = store.get(code)
    if not entry:
        return {"error": "Short URL not found", "status": 404}

    # Check expiry
    if entry["expires_at"] and time.time() &gt; entry["expires_at"]:
        del store[code]
        return {"error": "Short URL has expired", "status": 410}

    entry["clicks"] += 1
    return {
        "long_url": entry["long_url"],
        "clicks":   entry["clicks"],
        "status":   302,
    }

# Simulate clicks
for _ in range(3):
    result = resolve("rpy")
    print(f"Redirect to: {result['long_url']}  (clicks: {result['clicks']})")

# Non-existent code
