Fetching usersuseEffect timing <pre><code>import { useState, useEffect } from "react";

const API = process.env.REACT_APP_API_URL || "";

function UserList() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() =&gt; {
    fetch(`${API}/api/users`)
      .then(r =&gt; { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
      .then(data =&gt; { setUsers(data); setLoading(false); })
      .catch(err =&gt; { setError(err.message); setLoading(false); });
  }, []);  // [] = run once on mount

  if (loading) return &lt;p&gt;Loading…&lt;/p&gt;;
  if (error)   return &lt;p&gt;Error: {error}&lt;/p&gt;;
  return &lt;DataTable rows={users} /&gt;;
}
</code></pre> <pre><code>Component mounts
    └─► useEffect callback fires
            └─► fetch() → promise
                    └─► .then(setUsers)  → re-render with data
</code></pre> <p>Empty dependency array <code>[]</code></p> <p>Pass an empty array as the second argument to run the effect only once (on mount). Omitting it runs on every render — that causes infinite loops with data-fetching effects.</p>

