Flask — full endpoint <pre><code>from flask import Flask, request, jsonify
import csv, io

app = Flask(__name__)
REQUIRED = {"name", "age", "salary"}

@app.post("/upload/employees")
def upload_employees():
    f = request.files.get("file")
    if not f:
        return jsonify({"error": "No file uploaded"}), 400

    content = f.stream.read().decode("utf-8")
    reader  = csv.DictReader(io.StringIO(content))

    # Column validation
    missing = REQUIRED - set(reader.fieldnames or [])
    if missing:
        return jsonify({"error": f"Missing columns: {sorted(missing)}"}), 422

    valid, errors = [], []
    for i, row in enumerate(reader, 2):
        try:
            validated = {
                "name":   row["name"].strip(),
                "age":    int(row["age"]),
                "salary": float(row["salary"]),
            }
            valid.append(validated)
        except (ValueError, KeyError) as e:
            errors.append({"row": i, "error": str(e)})

    return jsonify({
        "accepted": len(valid),
        "rejected": len(errors),
        "errors":   errors,
    }), 200 if not errors else 207   # 207 Multi-Status
</code></pre> <p>HTTP 207 Multi-Status</p> <p>Return <code>207</code> when some rows were accepted and some were rejected. Return <code>422 Unprocessable Entity</code> when the entire file is structurally invalid.</p>

Server-Sent Events (SSE) <pre><code>from flask import Flask, Response, request
import csv, io, json, time

app = Flask(__name__)

@app.post("/upload/progress")
def upload_with_progress():
    content = request.files["file"].stream.read().decode("utf-8")
    rows    = list(csv.DictReader(io.StringIO(content)))
    total   = len(rows)

    def generate():
        for i, row in enumerate(rows, 1):
            time.sleep(0.01)   # simulate processing
            pct = round(i / total * 100)
            yield f"data: {json.dumps({'processed': i, 'total': total, 'pct': pct})}\n\n"
        yield f"data: {json.dumps({'status': 'done', 'total': total})}\n\n"

    return Response(generate(), mimetype="text/event-stream")
